Consider the following program:

```python
def main():
    f1()
    f2(2)
    f3()
    return 0

def f1():
    return 1

def f2(x):
    f3()
    if x == 1:
        return f1()
    else:
        return x + f2(x-1)

def f3():
    return 5

main()
```

